const BASE = '/spiel/'
const NAV_TIMEOUT_MS = 4000
// ignoreVary: manche Server senden "Vary: Origin" - ein Modul-Import (CORS) fand sonst die vorab geladene Datei nicht.
const MATCH = { ignoreVary: true }

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(CORE.map((file) => BASE + file))))
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key.startsWith('jds-') && key !== CACHE).map((key) => caches.delete(key))))
      .then(() => self.clients.claim())
  )
})

// Fehlt eine Datei auf dem Server (z.B. waehrend eines Deploys), antwortet der SPA-Fallback mit index.html und Status 200.
// Ohne diese Pruefung landete die HTML-Seite unter dem Namen des Bildes im Cache und das Bild blieb fuer diese Version leer.
// Gleiches gilt fuer leere 200-Antworten (vom CDN schon beobachtet).
function brauchbar(path, response) {
  if (!response || response.status !== 200) return false
  if (response.headers.get('Content-Length') === '0') return false
  const html = (response.headers.get('Content-Type') || '').startsWith('text/html')
  return !html || path.endsWith('/') || path.endsWith('.html')
}

// Safari (iOS und macOS) fragt Audio und Video mit "Range"-Anfragen ab und spielt nichts ab, wenn der Service Worker darauf mit der
// ganzen Datei (Status 200) antwortet - darum wird der gewuenschte Ausschnitt als 206 aus der gespeicherten Datei geschnitten.
async function rangeResponse(request, response) {
  const match = /^bytes=([0-9]*)-([0-9]*)$/.exec(request.headers.get('range') || '')
  if (!match || (match[1] === '' && match[2] === '')) return response
  const buffer = await response.arrayBuffer()
  const size = buffer.byteLength
  const start = match[1] === '' ? Math.max(0, size - Number(match[2])) : Number(match[1])
  const end = match[1] === '' || match[2] === '' ? size - 1 : Math.min(Number(match[2]), size - 1)
  if (start >= size || start > end) {
    return new Response(null, { status: 416, headers: { 'Content-Range': 'bytes */' + size } })
  }
  return new Response(buffer.slice(start, end + 1), {
    status: 206,
    statusText: 'Partial Content',
    headers: {
      'Content-Type': response.headers.get('Content-Type') || 'application/octet-stream',
      'Content-Length': String(end - start + 1),
      'Content-Range': 'bytes ' + start + '-' + end + '/' + size
    }
  })
}

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return
  const url = new URL(request.url)
  if (url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return

  if (request.mode === 'navigate') {
    const network = fetch(request).then((response) => {
      if (response.status === 200 && url.pathname === BASE) {
        const copy = response.clone()
        caches.open(CACHE).then((cache) => cache.put(BASE + 'index.html', copy)).catch(() => {})
      }
      return response
    })
    // Bei sehr langsamem Netz (NAV_TIMEOUT_MS) kommt die zwischengespeicherte Startseite, ohne Netz sowieso.
    event.respondWith(
      caches.match(BASE + 'index.html', MATCH).then((cached) =>
        cached
          ? Promise.race([network, new Promise((resolve) => setTimeout(() => resolve(cached), NAV_TIMEOUT_MS))]).catch(() => cached)
          : network
      )
    )
    return
  }

  const wantsRange = request.headers.has('range')
  event.respondWith(
    caches.match(request, MATCH).then((cached) => {
      if (cached && brauchbar(url.pathname, cached)) return wantsRange ? rangeResponse(request, cached) : cached
      return fetch(request).then((response) => {
        // Nur vollstaendige Antworten speichern: cache.put wirft bei 206 (Teilantwort) einen Fehler.
        // Ein frueher gespeicherter Fehlgriff (siehe brauchbar) wird dabei ueberschrieben.
        if (response.type === 'basic' && brauchbar(url.pathname, response)) {
          const copy = response.clone()
          caches.open(CACHE).then((cache) => cache.put(request, copy)).catch(() => {})
        }
        return response
      })
    })
  )
})

// Hintergrund-Nachladen aller noch fehlenden Dateien (drei gleichzeitig). iOS beendet Service Worker nach kurzer Zeit - darum
// arbeitet jede Nachricht nur ein Zeitbudget ab und meldet, wie viele Dateien noch fehlen; die Seite fragt dann erneut an.
const WARMUP_BUDGET_MS = 15000

self.addEventListener('message', (event) => {
  if (!event.data || event.data.type !== 'warmup') return
  const client = event.source
  event.waitUntil(
    caches.open(CACHE).then(async (cache) => {
      const deadline = Date.now() + WARMUP_BUDGET_MS
      const queue = []
      for (const file of REST) {
        if (!brauchbar(BASE + file, await cache.match(BASE + file, MATCH))) queue.push(BASE + file)
      }
      const total = queue.length
      async function worker() {
        while (queue.length > 0 && Date.now() < deadline) {
          const path = queue.shift()
          try {
            const response = await fetch(path)
            if (brauchbar(path, response)) await cache.put(path, response)
          } catch {
            // offline oder Datei fehlt - beim naechsten Mal erneut versuchen
          }
        }
      }
      await Promise.all([worker(), worker(), worker()])
      if (client) client.postMessage({ type: 'warmup-progress', remaining: queue.length, total })
    })
  )
})
